CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_token_hash_idx ON sessions(token_hash);
CREATE TABLE IF NOT EXISTS auth_identities (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider TEXT NOT NULL, provider_subject TEXT NOT NULL, email TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(provider, provider_subject), UNIQUE(user_id, provider));
CREATE TABLE IF NOT EXISTS study_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, paper_id TEXT, subject TEXT NOT NULL, grade TEXT NOT NULL, focus TEXT NOT NULL, status TEXT NOT NULL, is_demo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS study_requests_user_idx ON study_requests(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS user_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, news_topics TEXT NOT NULL, marketplace_interests TEXT NOT NULL, marketplace_area TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_items (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, portal TEXT NOT NULL, item_key TEXT NOT NULL, title TEXT NOT NULL, metadata TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id, portal, item_key));
CREATE INDEX IF NOT EXISTS saved_items_user_portal_idx ON saved_items(user_id, portal, created_at DESC);
CREATE TABLE IF NOT EXISTS contact_submissions (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL, topic TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS community_posts (id TEXT PRIMARY KEY, author_id TEXT REFERENCES users(id) ON DELETE SET NULL, author_label TEXT NOT NULL, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, summary TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL, is_internal INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, published_at TEXT);
CREATE INDEX IF NOT EXISTS community_posts_status_published_idx ON community_posts(status, published_at DESC);
CREATE TABLE IF NOT EXISTS user_roles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'student', institution TEXT, verified INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS generated_papers (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, paper_size TEXT NOT NULL, board TEXT NOT NULL, grade TEXT NOT NULL, subject TEXT NOT NULL, chapters_json TEXT NOT NULL, provider TEXT NOT NULL, status TEXT NOT NULL, paper_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS generated_papers_user_idx ON generated_papers(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS generated_paper_cache (generation_key TEXT PRIMARY KEY, provider TEXT NOT NULL, paper_json TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_attempts (id TEXT PRIMARY KEY, paper_id TEXT NOT NULL REFERENCES generated_papers(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, provider TEXT NOT NULL, answers_json TEXT NOT NULL, score_json TEXT NOT NULL, started_at TEXT NOT NULL, submitted_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_feedback (id TEXT PRIMARY KEY, paper_id TEXT NOT NULL REFERENCES generated_papers(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, category TEXT NOT NULL, comment TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS test_rooms (id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, paper_id TEXT NOT NULL REFERENCES generated_papers(id) ON DELETE CASCADE, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS test_attendees (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES test_rooms(id) ON DELETE CASCADE, name TEXT NOT NULL, roll_number TEXT NOT NULL, status TEXT NOT NULL, options_filled TEXT, score INTEGER, ai_evaluation TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS news_articles (id TEXT PRIMARY KEY, canonical_url TEXT NOT NULL UNIQUE, title TEXT NOT NULL, source TEXT NOT NULL, summary TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL, image_url TEXT, published_at TEXT NOT NULL, ingested_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS news_perspectives (id TEXT PRIMARY KEY, article_id TEXT NOT NULL REFERENCES news_articles(id) ON DELETE CASCADE, provider TEXT NOT NULL, analysis_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_listings (id TEXT PRIMARY KEY, title TEXT NOT NULL, place TEXT NOT NULL, area TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, price_label TEXT, expires_at TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, metadata_json TEXT NOT NULL, created_at TEXT NOT NULL);
INSERT INTO schema_migrations (version, applied_at) VALUES ('0001_initial', CURRENT_TIMESTAMP::TEXT) ON CONFLICT (version) DO NOTHING;
